"""Random signed fields, some forced negative and some forced positive, with
unrelated flag bits scattered around the field on purpose."""


def generate(rng, count):
    builders = (_anything, _forced_negative, _forced_positive, _whole_register)
    return [builders[i % len(builders)](rng, i + 1) for i in range(count)]


def _case(name, reg, start, width, description=""):
    return {
        "name": name,
        "stdin": "%X %d %d\n" % (reg, start, width),
        "description": description,
    }


def _anything(rng, index):
    reg = rng.randrange(0, 2 ** 32)
    start = rng.randrange(24)
    width = rng.randint(2, 32 - start)
    return _case("a random signed field #%d" % index, reg, start, width)


def _flagged(rng, start, width, field):
    field_mask = ((1 << width) - 1) << start
    flags = rng.randrange(0, 2 ** 32) & ~field_mask
    return (flags | (field << start)) & 0xFFFFFFFF


def _forced_negative(rng, index):
    start = rng.randrange(24)
    width = rng.randint(2, 32 - start)
    field = rng.randrange(1 << (width - 1), 1 << width)  # field's sign bit set
    reg = _flagged(rng, start, width, field)
    return _case("a negative reading with flags around it #%d" % index,
                 reg, start, width,
                 "The field's own top bit is set; that is what makes it "
                 "negative, not anything elsewhere in the register.")


def _forced_positive(rng, index):
    start = rng.randrange(24)
    width = rng.randint(2, 32 - start)
    field = rng.randrange(0, 1 << (width - 1))  # field's sign bit clear
    reg = _flagged(rng, start, width, field)
    return _case("a positive reading with flags around it #%d" % index,
                 reg, start, width)


def _whole_register(rng, index):
    reg = rng.randrange(0, 2 ** 32)
    return _case("the whole register, width = 32 #%d" % index, reg, 0, 32)
